//! The UseDefs attribute of Frames, checked against the C library.
//!
//! `use_defs_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/use_defs_probe.c`. UseDefs defaults to true; a
//! CmpFrame takes an unset value from its first component and a FrameSet
//! from its current Frame, to which setting it on the FrameSet goes
//! (cmpframe.c, frameset.c `GetUseDefs`). A dump writes `UseDfs` when it is
//! set (object.c `Dump`).

use crate::common::native_dump;
#[path = "use_defs_oracle/cases.rs"]
mod cases;

use ast_core::frames::{
    BasicFrameBuilder, CmpFrame, Frame, FrameRef, FrameSet, SkyFrame, SpecFrame, TimeFrame,
};
use ast_core::mappings::UnitMap;
use ast_core::{AnyObject, from_native_string};

fn basic(naxes: usize) -> ast_core::frames::BasicFrame {
    BasicFrameBuilder::new(naxes).build().unwrap()
}

fn off<F: Frame>(mut f: F) -> F {
    f.set_use_defs(false).unwrap();
    f
}

fn build(name: &str) -> AnyObject {
    match name {
        "frame_default" => AnyObject::BasicFrame(basic(1)),
        "frame_off" => AnyObject::BasicFrame(off(basic(1))),
        "frame_off_ident" => {
            let mut f = off(basic(1));
            f.set_ident("Me");
            AnyObject::BasicFrame(f)
        }
        "spec_off" => AnyObject::SpecFrame(off(SpecFrame::unset_system())),
        "sky_on" => {
            let mut f = SkyFrame::unset_system();
            f.set_use_defs(true).unwrap();
            AnyObject::SkyFrame(f)
        }
        "time_off" => AnyObject::TimeFrame(off(TimeFrame::unset_system())),
        "cmp_from_first" => AnyObject::CmpFrame(CmpFrame::new(
            Box::new(off(SkyFrame::unset_system())),
            Box::new(basic(1)),
        )),
        "cmp_second_ignored" => AnyObject::CmpFrame(CmpFrame::new(
            Box::new(basic(1)),
            Box::new(off(SkyFrame::unset_system())),
        )),
        "frameset_from_current" | "frameset_own" => {
            let mut fs = FrameSet::new(Box::new(basic(2)));
            fs.add_frame(
                FrameRef::Base,
                Box::new(UnitMap::new(2)),
                Box::new(off(basic(2))),
            )
            .unwrap();
            if name == "frameset_own" {
                fs.set_use_defs(true).unwrap();
            }
            AnyObject::FrameSet(fs)
        }
        other => panic!("no Rust set-up for {other}"),
    }
}

#[test]
fn use_defs_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(name, value, set, dump) in cases::CASES {
        let obj = build(name);
        let f = obj.as_frame().expect("a Frame");
        let got = (f.use_defs(), f.test_use_defs());
        if got != (value, set) {
            failures.push(format!("{name}: got {got:?}, C gives {:?}", (value, set)));
        }
        let written = native_dump(&obj).unwrap();
        if written != dump {
            failures.push(format!("{name}: dump differs\n{written}\nC:\n{dump}"));
        }
        let read = from_native_string(dump).unwrap();
        let back = read.as_frame().expect("a Frame");
        if (back.use_defs(), back.test_use_defs()) != (value, set) {
            failures.push(format!(
                "{name}: read back as {:?}",
                (back.use_defs(), back.test_use_defs())
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
